package storage

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"database/sql"
)

// StageOutputResource is an immutable, schema-qualified Provider result object.
// Resource references are opaque and generated by Researchflow Storage.
type StageOutputResource struct {
	Ref                 string
	RunRef              string
	StageRef            string
	AttemptRef          string
	Kind                string
	StageCode           string
	TemplateVersion     string
	RegistryVersion     string
	RegistryFingerprint string
	OutputType          string
	SchemaVersion       string
	SchemaRef           string
	Content             []byte
	CreatedAt           string
}

func newStageOutputResourceRef() (string, error) {
	random := make([]byte, 32)
	if _, err := rand.Read(random); err != nil {
		return "", fmt.Errorf("generate Stage Output resource reference: %w", err)
	}
	return "stage-output:" + base64.RawURLEncoding.EncodeToString(random), nil
}

// GetStageOutputResource retrieves one immutable result by its opaque reference.
// Callers must still enforce the resource kind expected by their own contract.
func (r *MySQLRunRepository) GetStageOutputResource(ctx context.Context, ref string) (StageOutputResource, error) {
	if r == nil || r.db == nil {
		return StageOutputResource{}, errors.New("researchflow SQL database is not configured")
	}
	if strings.TrimSpace(ref) == "" || ref != strings.TrimSpace(ref) {
		return StageOutputResource{}, errors.New("Researchflow Stage Output resource reference is required")
	}
	var resource StageOutputResource
	err := r.db.QueryRowContext(ctx, `SELECT
		resource_ref, run_ref, stage_ref, attempt_ref, resource_kind, stage_code,
		template_version, registry_version, registry_fingerprint, output_type,
		schema_version, schema_ref, content, created_at
		FROM researchflow_stage_output_resources WHERE resource_ref = ?`, ref,
	).Scan(
		&resource.Ref, &resource.RunRef, &resource.StageRef, &resource.AttemptRef,
		&resource.Kind, &resource.StageCode, &resource.TemplateVersion,
		&resource.RegistryVersion, &resource.RegistryFingerprint, &resource.OutputType,
		&resource.SchemaVersion, &resource.SchemaRef, &resource.Content, &resource.CreatedAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return StageOutputResource{}, errors.New("Researchflow Stage Output resource not found")
		}
		return StageOutputResource{}, fmt.Errorf("read Researchflow Stage Output resource: %w", err)
	}
	resource.Content = append([]byte(nil), resource.Content...)
	return resource, nil
}
